2022년 월드컵 포르투갈전에서 결승골을 넣은 대한민국 선수|황희찬
한 선수가 한 경기에서 세 골을 넣는 축구 기록|해트트릭

]==]

local function trim(s)
    return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end
local function cleanText(s)
    s = tostring(s or ""):gsub("<[^>]->", "")
    s = s:gsub("&amp;", "&"):gsub("&lt;", "<"):gsub("&gt;", ">")
    s = s:gsub("&quot;", '"'):gsub("&apos;", "'"):gsub(" ", " ")
    return trim(s:gsub("%s+", " "))
end
local function normalized(s)
    return (cleanText(s):lower():gsub("[%s%p]", ""):gsub("·", ""):gsub("ㆍ", ""))
end
local function charCount(s)
    local n = utf8.len(s)
    return n or #s
end
local baseDB, quizDB, categories = {}, {}, {}
local category = "일반상식"
for line in rawDB:gmatch("[^\r\n]+") do
    local heading = line:match("^%-%- %[(.-)%]$")
    if heading then
        category = heading
    elseif not line:match("^%-%-") then
        local k, a = line:match("^(.-)|(.*)$")
        if k and trim(k) ~= "" and trim(a) ~= "" then
            k, a = trim(k), trim(a)
            baseDB[k], quizDB[k], categories[k] = a, a, category
        end
    end
end

-- v2/v6/v7 사전, 평면 JSON, 질문 목록 JSON, 질문|정답 텍스트 지원.
local dbFile = "GoldenBell_QuizDB.json"
local backupFile = "GoldenBell_QuizDB.backup.json"
local overrides, deleted = {}, {}
local loadWarning, startupMessage = nil, "저장된 사용자 사전이 없습니다."
local function parseImport(content)
    if type(content) ~= "string" or trim(content) == "" then error("사전 내용이 비어 있습니다.") end
    content=trim(content:gsub("^\239\187\191", ""))
    local additions,removals={},{}
    local function pair(k,a)
        if type(k)~="string" or type(a)~="string" then error("질문과 정답은 문자열이어야 합니다.") end
        k,a=trim(k),trim(a)
        if k=="" or a=="" then error("빈 질문이나 빈 정답이 있습니다.") end
        additions[k]=a
    end
    if content:sub(1,1)=="{" or content:sub(1,1)=="[" then
        local data=HttpService:JSONDecode(content)
        if type(data)~="table" then error("JSON 사전은 객체나 목록이어야 합니다.") end
        if data.version==2 then
            if data.overrides~=nil and type(data.overrides)~="table" then error("overrides 형식이 잘못되었습니다.") end
            if data.deleted~=nil and type(data.deleted)~="table" then error("deleted 형식이 잘못되었습니다.") end
            for k,a in pairs(data.overrides or {}) do pair(k,a) end
            for k,v in pairs(data.deleted or {}) do
                if type(k)~="string" or type(v)~="boolean" then error("삭제 목록 형식이 잘못되었습니다.") end
                if v then removals[k]=true end
            end
        else
            local source=data.quizDB or data.questions or data.entries or data.data or data
            if type(source)~="table" then error("질문 목록 형식이 잘못되었습니다.") end
            for k,a in pairs(source) do
                if type(k)=="number" then
                    if type(a)~="table" then error("질문 목록의 항목 형식이 잘못되었습니다.") end
                    pair(a.question or a.keyword or a.key or a[1],a.answer or a.value or a[2])
                else
                    pair(k,a)
                end
            end
        end
    else
        for line in content:gmatch("[^\r\n]+") do
            line=trim(line)
            if line~="" and not line:match("^%-%-") and not line:match("^#") then
                local k,a=line:match("^(.-)|(.*)$")
                if not k then error("질문|정답 형식이 아닌 줄: "..line:sub(1,100)) end
                pair(k,a)
            end
        end
    end
    if next(additions)==nil and next(removals)==nil then
        -- 빈 v2 백업도 읽을 수 있지만, 일반 빈 목록은 실수로 가져오지 않음.
        local compact=content:gsub("%s+", "")
        if not compact:find('"version":2',1,true) then error("가져올 질문·정답이 없습니다.") end
    end
    return additions,removals
end
local function mergeImport(additions,removals)
    local added,changed,removed,same=0,0,0,0
    for k,a in pairs(additions) do
        if quizDB[k]==nil then added=added+1
        elseif quizDB[k]~=a then changed=changed+1
        else same=same+1 end
        quizDB[k]=a
        overrides[k]=(baseDB[k]~=a) and a or nil
        deleted[k]=nil
    end
    for k in pairs(removals) do
        if quizDB[k]~=nil then removed=removed+1 end
        quizDB[k],overrides[k],deleted[k]=nil,nil,true
    end
    return added,changed,removed,same
end
local function readImportFile(path)
    path=trim(path)
    if path=="" then return false,"파일 이름을 입력하세요." end
    if type(readfile)~="function" then return false,"이 실행 환경은 파일 읽기를 지원하지 않습니다." end
    if type(isfile)=="function" then
        local ok,exists=pcall(isfile,path)
        if not ok then return false,"파일 확인 실패: "..tostring(exists) end
        if not exists then return false,"파일이 없습니다: "..path end
    end
    local ok,a,b=pcall(function()
        local content=readfile(path)
        return parseImport(content)
    end)
    if not ok then return false,"불러오기 실패: "..tostring(a) end
    return true,a,b
end
local loaded,a,b=readImportFile(dbFile)
if loaded then
    local added,changed,removed=mergeImport(a,b)
    startupMessage="기존 사전 자동 불러오기 완료 · 추가 "..added.." / 변경 "..changed.." / 삭제 "..removed
elseif type(isfile)=="function" and type(readfile)=="function" then
    local checked,exists=pcall(isfile,dbFile)
    if checked and exists then
        local recovered,c,d=readImportFile(backupFile)
        if recovered then
            mergeImport(c,d)
            startupMessage="기본 사전을 읽지 못해 이전 백업을 불러왔습니다."
            loadWarning=startupMessage.."\n"..tostring(a)
        else
            loadWarning=tostring(a).."\n백업 복원도 실패했습니다: "..tostring(c)
        end
    end
else
    startupMessage="파일 읽기를 지원하지 않는 환경입니다. 내용 붙여넣기를 이용하세요."
end
local function encodeCustom()
    return HttpService:JSONEncode({version=2,overrides=overrides,deleted=deleted})
end
local function saveDB()
    if type(writefile)~="function" then
        return false,"파일 저장을 지원하지 않습니다. 이번 실행에만 반영됩니다. 내보내기 내용을 복사해 보관하세요."
    end
    local ok,err=pcall(function()
        local payload=encodeCustom()
        if type(readfile)=="function" and type(isfile)=="function" and isfile(dbFile) then
            local previous=readfile(dbFile)
            -- 정상적으로 읽을 수 있는 이전 사전만 백업. 깨진 원본으로 정상 백업을 덮지 않음.
            local valid=pcall(parseImport,previous)
            if valid then writefile(backupFile,previous) end
        end
        writefile(dbFile,payload)
    end)
    if not ok then return false,"저장 실패: "..tostring(err) end
    return true
end

-- 설명형 질문은 조사·어미 차이를 흡수하되, 근거가 부족하거나 후보가 비슷하면 답을 내지 않음.
local singleTokens={}
for token in ("물 코 뇌 팔 발 귀 눈 피 뼈 꽃 빛 힘 열 잎 씨 강 산 해 달 땅 별 뿔 털 알 줄 실 집 먹 잡 쏘 날"):gmatch("%S+") do singleTokens[token]=true end
local ignoredTokens={}
for token in ("무엇 누구 어디 어느 어떤 얼마 몇 뜻 말 보통 가장 대표 주로 것 있다 한다 있는 하는 되는 같은 다른 대표적인 흔히 알려진 유명한 자주 매우 어떻게 무엇인가요 무엇일까요 무엇인가 무엇이라고 인가요 일까요 주세요 무엇일까"):gmatch("%S+") do ignoredTokens[token]=true end
local suffixes={"것일까요","무엇일까요","이라고","에서는","으로는","에게는","일까요","인가요","입니까","입니다","합니다","이라고","라는","하고","하며","하는","한다","되는","되고","에서","에게","처럼","보다","으로","까지","부터","거나","으며","으면","과의","와의","을","를","은","는","이","가","의","에","로","과","와","도","고"}
local function descriptionTokens(text)
    local result,seen={},{}
    text=cleanText(text):gsub("[%p]"," "):gsub("·"," ")
    for token in text:gmatch("%S+") do
        token=normalized(token)
        local original=token
        if not ignoredTokens[token] then
            for _,suffix in ipairs(suffixes) do
                if #token>#suffix and token:sub(-#suffix)==suffix then
                    local stem=token:sub(1,#token-#suffix)
                    if charCount(stem)>=2 or singleTokens[stem] then token=stem;break end
                end
            end
            if not ignoredTokens[token] and (charCount(token)>=2 or singleTokens[token]) and not seen[token] then
                seen[token]=true
                table.insert(result,token)
            end
        end
    end
    return result
end
local descriptionPostings={}
local function buildDescriptionIndex(rows)
    descriptionPostings={}
    for _,row in ipairs(rows) do
        if not row.term and not row.word and row.length>=10 then
            local tokens=descriptionTokens(row.key)
            if #tokens>=3 then
                row.tokens=tokens
                for _,token in ipairs(tokens) do
                    if not descriptionPostings[token] then descriptionPostings[token]={} end
                    table.insert(descriptionPostings[token],row)
                end
            end
        end
    end
end
local function matchDescription(question)
    local tokens=descriptionTokens(question)
    local hits={}
    for _,token in ipairs(tokens) do
        for _,row in ipairs(descriptionPostings[token] or {}) do hits[row]=(hits[row] or 0)+1 end
    end
    local bestAnswer,bestRow,bestScore,secondScore=nil,nil,-math.huge,-math.huge
    for row,count in pairs(hits) do
        if count>=3 and count/#row.tokens>=0.8 then
            local matched,total,rare=0,0,false
            for _,token in ipairs(row.tokens) do
                local frequency=#descriptionPostings[token]
                local weight=1+math.log(1+200/(frequency+1))
                total=total+weight
                for _,qtoken in ipairs(tokens) do
                    if token==qtoken then
                        matched=matched+weight
                        if frequency<=12 then rare=true end
                        break
                    end
                end
            end
            local coverage=matched/total
            if rare and coverage>=0.84 then
                local score=coverage+math.min(count,8)*0.02
                if score>bestScore then
                    if bestAnswer and bestAnswer~=row.answer then secondScore=math.max(secondScore,bestScore) end
                    bestAnswer,bestRow,bestScore=row.answer,row,score
                elseif row.answer~=bestAnswer then
                    secondScore=math.max(secondScore,score)
                end
            end
        end
    end
    if bestRow and bestScore-secondScore>=0.05 then return bestAnswer,bestRow.key,bestRow.category end
    return nil
end

-- 2. 검색 인덱스: 질문마다 3천 개 키를 다시 정렬하지 않음.
local index, forwardWords, reverseWords = {}, {}, {}
local chemicalNames,chemicalSymbols={},{}
local dbCount, baseCount, revision = 0, 0, 0
for _ in pairs(baseDB) do baseCount = baseCount + 1 end
local function rebuildIndex()
    index, forwardWords, reverseWords = {}, {}, {}
    chemicalNames,chemicalSymbols={},{}
    dbCount = 0
    for k, a in pairs(quizDB) do
        dbCount = dbCount + 1
        local row = {key=k, answer=a, norm=normalized(k), length=charCount(k), category=categories[k] or "사용자 추가"}
        table.insert(index, row)
        local elementName=k:match("^(.-)의 원소 기호$")
        local elementSymbol=k:match("^원소 기호 (.-)가 나타내는 원소$")
        if elementName then table.insert(chemicalNames,{name=elementName,key=k}) end
        if elementSymbol then table.insert(chemicalSymbols,{symbol=elementSymbol,name=a,key=k}) end
        local term = k:match("^(.-)를 영어로$")
        local word = k:match("^영어 단어 (.-)의 뜻$")
        if term then
            row.term = term
            table.insert(forwardWords, row)
        elseif word then
            row.word = word:lower()
            table.insert(reverseWords, row)
        end
    end
    local function longer(a,b)
        if a.length == b.length then return a.key < b.key end
        return a.length > b.length
    end
    table.sort(index, longer)
    table.sort(forwardWords, function(a,b)
        if #a.term == #b.term then return a.term < b.term end
        return #a.term > #b.term
    end)
    table.sort(reverseWords, function(a,b)
        if #a.word == #b.word then return a.word < b.word end
        return #a.word > #b.word
    end)
    table.sort(chemicalNames,function(a,b)
        if #a.name==#b.name then return a.name<b.name end
        return #a.name>#b.name
    end)
    table.sort(chemicalSymbols,function(a,b)
        if #a.symbol==#b.symbol then return a.symbol<b.symbol end
        return #a.symbol>#b.symbol
    end)
    buildDescriptionIndex(index)
    revision = revision + 1
end
rebuildIndex()

local function wordByte(b)
    return b and ((b>=48 and b<=57) or (b>=65 and b<=90) or (b>=97 and b<=122) or b>=128)
end
local function asciiWordByte(b)
    return b and ((b>=48 and b<=57) or (b>=65 and b<=90) or (b>=97 and b<=122))
end
local function safeFind(text, key)
    if key == "" then return false end
    local count, start = charCount(key), 1
    while true do
        local s,e = text:find(key,start,true)
        if not s then return false end
        if count > 2 then return true end
        local before, after = wordByte(text:byte(s-1)), wordByte(text:byte(e+1))
        if not before and (count > 1 or not after) then return true end
        start = e+1
    end
end
local function findEnglishWord(text, word)
    local start = 1
    while true do
        local s,e = text:find(word,start,true)
        if not s then return false end
        if not asciiWordByte(text:byte(s-1)) and not asciiWordByte(text:byte(e+1)) then return true end
        start = e+1
    end
end
local function findKoreanTerm(text, term)
    local start = 1
    while true do
        local s,e = text:find(term,start,true)
        if not s then return false end
        -- 앞말의 일부인 '쥐'가 '다람쥐'보다 먼저 선택되는 것을 막음.
        if not wordByte(text:byte(s-1)) then
            if not wordByte(text:byte(e+1)) then return true end
            local rest=text:sub(e+1)
            for _,particle in ipairs({"를","을","은","는","이","가","의","에","와","과","도"}) do
                if rest:sub(1,#particle)==particle and not wordByte(rest:byte(#particle+1)) then return true end
            end
        end
        start = e+1
    end
end

-- 원자 번호/원소 기호 질문의 흔한 어순 차이 처리. 답은 현재 사전에서만 읽음.
local function lookupChemistry(question)
    local compact=normalized(question)
    if not compact:find("원자번호",1,true) and not compact:find("원소기호",1,true) and not compact:find("화학기호",1,true) then return nil end
    local wantsNumber=compact:find("원자번호",1,true)~=nil
    local numbered=compact:gsub("원자번호가","원자번호"):gsub("원자번호는","원자번호"):gsub("원자번호은","원자번호")
    local number=numbered:match("원자번호(%d+)")
    local function answer(key)
        if quizDB[key] then return quizDB[key],key,categories[key] or "사용자 추가" end
        return nil
    end
    if number then
        local name=quizDB["원자 번호가 "..tonumber(number).."인 원소"]
        if name then
            if compact:find("기호",1,true) then return answer(name.."의 원소 기호") end
            return answer("원자 번호가 "..tonumber(number).."인 원소")
        end
    end
    -- 이름이 긴 원소부터 확인해 '인'이 '아인슈타이늄'보다 앞서지 않게 함.
    for _,row in ipairs(chemicalNames) do
        local name=row.name
        local appears
        if charCount(name)>=2 then appears=compact:find(name,1,true)
        else appears=findKoreanTerm(question,name) end
        if appears then
            if wantsNumber then return answer(name.."의 원자 번호") end
            return answer(row.key)
        end
    end
    for _,row in ipairs(chemicalSymbols) do
        if findEnglishWord(question,row.symbol) then
            if wantsNumber then return answer(row.name.."의 원자 번호") end
            return answer(row.key)
        end
    end
    return nil
end

-- 3. 동적 수학 계산. UTF-8 연산자를 바이트 문자 집합에 넣지 않음.
local function formatNumber(n)
    if n ~= n or n == math.huge or n == -math.huge then return nil end
    if math.abs(n) < 1e-10 then n=0 end
    if math.abs(n - math.floor(n+0.5)) < 1e-9 then return string.format("%.0f", n) end
    return (string.format("%.8f",n):gsub("0+$",""):gsub("%.$",""))
end
local function has(s, token) return s:find(token,1,true) ~= nil end
local function solveMath(question)
    local q = cleanText(question):lower()
    q = q:gsub("×","*"):gsub("÷","/"):gsub("−","-"):gsub("–","-")
    q = q:gsub("㎝","cm"):gsub("센티미터","cm"):gsub("㎟","mm2"):gsub("㎠","cm2")
    local compact = q:gsub("%s+","")
    local function positiveNumbers(s)
        local values = {}
        for number in s:gmatch("%d+%.?%d*") do table.insert(values,tonumber(number)) end
        return values
    end
    -- 도형 문제에서는 단위에 붙은 제곱 숫자를 길이로 해석하지 않음.
    local shapeq = compact:gsub("cm2", "cm"):gsub("m2", "m"):gsub("제%d+문제", "")
    local nums = positiveNumbers(shapeq)
    local area, perimeter = has(compact,"넓이"), has(compact,"둘레")
    local lengthUnit
    local mixedUnit = false
    for u in shapeq:gmatch("%d+%.?%d*([a-z]+)") do
        if u=="mm" or u=="cm" or u=="m" or u=="km" then
            if lengthUnit and lengthUnit ~= u then mixedUnit=true end
            lengthUnit=u
        end
    end
    if (area or perimeter) and not mixedUnit then
        if has(compact,"정사각형") and nums[1] and nums[1] > 0 then
            return formatNumber(area and nums[1]^2 or nums[1]*4)
        elseif has(compact,"직사각형") and nums[1] and nums[2] and nums[1]>0 and nums[2]>0 then
            return formatNumber(area and nums[1]*nums[2] or (nums[1]+nums[2])*2)
        elseif has(compact,"삼각형") and area and nums[1] and nums[2] and has(compact,"밑변") and has(compact,"높이") then
            return formatNumber(nums[1]*nums[2]/2)
        elseif (has(compact,"원의") or has(compact,"원둘레") or has(compact,"원넓이")) and nums[1] then
            local diameter = has(compact,"지름") and not has(compact,"반지름")
            local radius = has(compact,"반지름")
            if diameter or radius then
                local r=diameter and nums[1]/2 or nums[1]
                local pi=3.14
                local customPi=compact:match("원주율[%=:은을]*([%d%.]+)")
                if customPi then pi=tonumber(customPi) or pi end
                return formatNumber(area and r*r*pi or 2*r*pi)
            end
        end
    end
    local arithmetic = has(q,"계산") or has(q,"얼마") or has(q,"값") or has(q,"=") or has(q,"답")
    local exprq = compact:gsub("[xX]","*")
    -- 괄호 없는 하나의 이항식만 계산. 연쇄식을 앞부분만 계산하지 않음.
    local a,op,b = exprq:match("([%-]?%d+%.?%d*)([%+%-%*/])([%-]?%d+%.?%d*)")
    if a and (arithmetic or exprq:match("^[%-]?%d+%.?%d*[%+%-%*/][%-]?%d+%.?%d*%??$")) then
        local expression = a..op..b
        local rest = exprq:gsub(expression:gsub("(%W)","%%%1"),"",1)
        if not rest:find("[%+%*/]") and not rest:find("%-%d") and not has(q,"(") and not has(q,")") then
            a,b=tonumber(a),tonumber(b)
            if op=="+" then return formatNumber(a+b) end
            if op=="-" then return formatNumber(a-b) end
            if op=="*" then return formatNumber(a*b) end
            if op=="/" and b~=0 then return formatNumber(a/b) end
        end
    end
    local a2,b2=q:match("(%d+%.?%d*)에서%s*(%d+%.?%d*)[을를]+%s*빼")
    if a2 then return formatNumber(tonumber(a2)-tonumber(b2)) end
    return nil
end

-- 실제 명칭과 게임이 받는 짧은 답 표기를 분리. 기존 사용자 JSON에도 적용.
local function preferredGameAnswer(question,answer)
    if not answer then return nil end
    local a=normalized(answer:gsub("%b()",""):gsub("（.-）",""))
    local statueAliases={
        ["구세주상"]=true,["구세주그리스도상"]=true,["구원자그리스도상"]=true,
        ["그리스도구세주상"]=true,["그리스도구원자상"]=true,["리우예수상"]=true,
        ["크리스토레덴토르"]=true,["christtheredeemer"]=true,["cristoredentor"]=true,
    }
    if statueAliases[a] then return "예수상" end
    if a=="킬리안음바페" or a=="kylianmbappe" or a=="kylianmbappé" or a=="mbappe" or a=="mbappé" then return "음바페" end
    local q=normalized(question)
    local moving=q:find("전입",1,true) and q:find("신고",1,true)
    local place=q:find("행정기관",1,true) or q:find("동네",1,true) or q:find("하러가는",1,true)
        or q:find("어느기관",1,true) or q:find("어디",1,true)
    local online=q:find("온라인",1,true) or q:find("인터넷",1,true) or q:find("사이트",1,true) or q:find("홈페이지",1,true)
    local modernName=q:find("현재명칭",1,true) or q:find("바뀐이름",1,true) or q:find("지금이름",1,true)
    if moving and place and not online and not modernName then
        if a=="주민센터" or a=="동주민센터" or a=="행정복지센터" or a=="동행정복지센터" or a=="우선" then return "동사무소" end
    end
    return answer
end

local function lookupRaw(question)
    local q = cleanText(question)
    local lower, norm = q:lower(), normalized(q)
    local direct = quizDB[q]
    if direct then return direct, q, categories[q] or "사용자 추가" end
    local chemistryAnswer,chemistryKey,chemistryCategory=lookupChemistry(q)
    if chemistryAnswer then return chemistryAnswer,chemistryKey,chemistryCategory end
    -- 영어 단어가 직접 나온 한국어 뜻 문제를 먼저 처리.
    if has(q,"뜻") or has(q,"우리말") or has(q,"한국어") or has(q,"의미") or has(q,"한글로") then
        for _,row in ipairs(reverseWords) do
            if findEnglishWord(lower,row.word) then return row.answer,row.key,row.category end
        end
    end
    if has(q,"영어") or has(q,"영문") or has(q,"영단어") then
        for _,row in ipairs(forwardWords) do
            if findKoreanTerm(q,row.term) then return row.answer,row.key,row.category end
        end
    end
    local mathAnswer=solveMath(q)
    if mathAnswer then return mathAnswer,"수학 계산","수학" end
    -- 긴 설명 우선. 공백/따옴표/문장부호 차이는 항목 추가 없이 처리.
    for _,row in ipairs(index) do
        local isForward = row.term ~= nil
        local isReverse = row.word ~= nil
        if not isForward and not isReverse and row.key~=row.answer then
            if safeFind(q,row.key) or (row.length>=4 and has(norm,row.norm)) then
                return row.answer,row.key,row.category
            end
        end
    end
    return matchDescription(q)
end

local function lookupWorldCupPerson(question)
    local q=normalized(question)
    if not (q:find("선수",1,true) or q:find("공격수",1,true)) then return nil end
    for _,target in ipairs({"몇","얼마","나라는","국가는","어느나라","어떤나라","국적","어느팀","우승국","준우승국","득점수","점수","감독은","감독의이름","주심은","골키퍼는"}) do
        if q:find(target,1,true) then return nil end
    end
    local final=q:find("결승",1,true) and q:find("월드컵",1,true)
    local three=q:find("세골",1,true) or q:find("3골",1,true) or q:find("해트트릭",1,true)
    local modern=q:find("2022",1,true) or q:find("카타르",1,true) or (q:find("프랑스",1,true) and q:find("준우승",1,true))
    if final and three and modern then
        local key="2022년 월드컵 결승전에서 해트트릭을 기록한 프랑스 선수"
        if quizDB[key] then return quizDB[key],key,categories[key] end
    end
    return nil
end

local function lookup(question)
    local answer,key,category=lookupWorldCupPerson(question)
    if not answer then answer,key,category=lookupRaw(question) end
    local target=normalized(question)
    if key and key:find("선수",1,true) and (target:find("감독은",1,true) or target:find("감독의이름",1,true) or target:find("어느나라",1,true) or target:find("국적",1,true) or target:find("골키퍼는",1,true) or target:find("주심은",1,true)) then
        return nil
    end
    return preferredGameAnswer(question,answer),key,category
end

-- 웹 검색은 HTML을 텍스트로만 읽음. 검색 페이지의 코드/스크립트는 실행하지 않음.
-- DuckDuckGo HTML 기본. 검색 제공자의 CAPTCHA/차단은 오류로 표시.
-- HTML 검색은 정답 전용 API가 아니므로 후보 일치 규칙을 통과할 때만 자동 입력 후보로 사용.
local WebSearch={}
function WebSearch.urlEncode(text)
    return (tostring(text):gsub("([^%w%-_%.~])",function(c) return string.format("%%%02X",string.byte(c)) end))
end
function WebSearch.urlDecode(text)
    return (tostring(text):gsub("%+"," "):gsub("%%(%x%x)",function(h) return string.char(tonumber(h,16)) end))
end
function WebSearch.decodeHtml(text)
    local named={amp="&",lt="<",gt=">",quot='"',apos="'",nbsp=" ",ndash="–",mdash="—",hellip="…",lsquo="‘",rsquo="’",ldquo="“",rdquo="”"}
    text=tostring(text or "")
    text=text:gsub("&#[xX](%x+);?",function(h)
        local ok,c=pcall(utf8.char,tonumber(h,16))
        return ok and c or " "
    end):gsub("&#(%d+);?",function(n)
        local ok,c=pcall(utf8.char,tonumber(n))
        return ok and c or " "
    end)
    return (text:gsub("&([%a]+);",function(n) return named[n] or " " end))
end
function WebSearch.plain(html)
    local s=tostring(html or "")
    s=s:gsub("<[sS][cC][rR][iI][pP][tT][^>]*>.-</[sS][cC][rR][iI][pP][tT]%s*>"," ")
    s=s:gsub("<[sS][tT][yY][lL][eE][^>]*>.-</[sS][tT][yY][lL][eE]%s*>"," ")
    local inline={b=true,strong=true,span=true,em=true,i=true,u=true}
    s=s:gsub("<(/?)([%w]+)([^>]*)>",function(closing,tag,attrs)
        return inline[tag:lower()] and "" or " "
    end)
    return trim(WebSearch.decodeHtml(s):gsub("%s+"," "))
end
function WebSearch.attr(attrs,name)
    return attrs:match(name..'%s*=%s*"(.-)"') or attrs:match(name.."%s*=%s*'(.-)'")
end
-- class를 가진 요소를 같은 태그의 중첩 깊이까지 세어 추출.
function WebSearch.blocks(html,classToken,limit)
    local out,pos={},1
    while #out<(limit or 12) do
        local s,e,tag,attrs=html:find("<([%w]+)([^>]*)>",pos)
        if not s then break end
        pos=e+1
        local class=WebSearch.attr(attrs,"class") or ""
        if (" "..class:gsub("%s+"," ").." "):find(" "..classToken.." ",1,true) then
            local depth,scan,finish=1,e+1,nil
            while depth>0 do
                local ns,ne,closing,nextTag,nextAttrs=html:find("<(/?)([%w]+)([^>]*)>",scan)
                if not ns then break end
                if nextTag:lower()==tag:lower() then
                    if closing=="/" then depth=depth-1
                    elseif not nextAttrs:match("/%s*$") then depth=depth+1 end
                end
                scan=ne+1
                if depth==0 then finish=ns;break end
            end
            if finish then table.insert(out,{html=html:sub(e+1,finish-1),attrs=attrs}) end
        end
    end
    return out
end
function WebSearch.cleanUrl(url)
    url=WebSearch.decodeHtml(url or "")
    local redirect=url:match("[?&]uddg=([^&]+)")
    if redirect then url=WebSearch.urlDecode(redirect) end
    local google=url:match("^/url%?q=([^&]+)") or url:match("^/url%?url=([^&]+)")
    if google then url=WebSearch.urlDecode(google) end
    if not url:match("^https?://") then return nil end
    return url
end
function WebSearch.host(url)
    local host=(url or ""):match("^https?://([^/%?#:]+)")
    if not host then return nil end
    return host:lower():gsub("^www%.","")
end
function WebSearch.blocked(html,status)
    if status==403 or status==429 or status==202 then return true end
    local lower=tostring(html or ""):lower()
    local markers={"anomaly.js","anomaly-modal","g-recaptcha","unusual traffic","automated queries","verify you are human","bots use duckduckgo too","challenge-form","captcha-form"}
    for _,token in ipairs(markers) do if lower:find(token,1,true) then return true end end
    return false
end
function WebSearch.httpClient()
    if type(request)=="function" then return request,"request" end
    if type(http_request)=="function" then return http_request,"http_request" end
    if type(ENV.request)=="function" then return ENV.request,"getgenv().request" end
    if type(ENV.http_request)=="function" then return ENV.http_request,"getgenv().http_request" end
    if type(http)=="table" and type(http.request)=="function" then return http.request,"http.request" end
    return nil,"HttpGet 대체 경로"
end
function WebSearch.fetch(url)
    local client,path=WebSearch.httpClient()
    local ok,response=pcall(function()
        if client then
            return client({Url=url,Method="GET",Headers={Accept="text/html",["Accept-Language"]="ko-KR,ko;q=0.9,en;q=0.6"},Timeout=6})
        end
        return {StatusCode=200,Body=game:HttpGet(url)}
    end)
    if not ok then return nil,"HTTP 요청 실패: "..tostring(response),false end
    if type(response)=="string" then response={StatusCode=200,Body=response} end
    if type(response)~="table" then return nil,"지원되지 않는 HTTP 응답 형식 ("..path..")",false end
    local status=tonumber(response.StatusCode or response.Status or response.status_code or response.status) or 0
    local body=response.Body or response.body
    if type(body)~="string" then return nil,"HTML 응답 본문이 없습니다.",false end
    if WebSearch.blocked(body,status) then return nil,"검색 제공자가 CAPTCHA/요청 차단을 반환했습니다.",true end
    if status~=0 and (status<200 or status>=300) then return nil,"HTTP 상태 "..status,false end
    if #body>700000 then body=body:sub(1,700000) end
    if body=="" then return nil,"빈 검색 응답입니다.",false end
    return body,nil,false
end
function WebSearch.records(html,engine)
    local results,seen={},{}
    local function add(title,snippet,url,raw)
        url=WebSearch.cleanUrl(url)
        local host=WebSearch.host(url)
        if not host or seen[url] then return end
        if host:find("duckduckgo.com",1,true) or host=="google.com" or host:find("google.com.",1,true) then return end
        title,snippet=WebSearch.plain(title),WebSearch.plain(snippet)
        if title=="" or snippet=="" then return end
        seen[url]=true
        table.insert(results,{title=title,snippet=snippet,url=url,host=host,raw=raw or ""})
    end
    if engine=="DuckDuckGo" then
        for _,block in ipairs(WebSearch.blocks(html,"result__body",20)) do
            local titles=WebSearch.blocks(block.html,"result__a",1)
            local snippets=WebSearch.blocks(block.html,"result__snippet",1)
            if titles[1] and snippets[1] then
                add(titles[1].html,snippets[1].html,WebSearch.attr(titles[1].attrs,"href"),snippets[1].html)
            end
        end
        if #results==0 then
            local titles=WebSearch.blocks(html,"result__a",20)
            local snippets=WebSearch.blocks(html,"result__snippet",20)
            for i=1,math.min(#titles,#snippets) do
                add(titles[i].html,snippets[i].html,WebSearch.attr(titles[i].attrs,"href"),snippets[i].html)
            end
        end
    else
        for _,containerClass in ipairs({"MjjYud","tF2Cxc","Gx5Zad"}) do
            for _,block in ipairs(WebSearch.blocks(html,containerClass,16)) do
                local title=block.html:match("<[hH]3[^>]*>(.-)</[hH]3>")
                if title then
                    local url
                    for attrs,inside in block.html:gmatch("<[aA]([^>]*)>(.-)</[aA]>") do
                        if inside:find("<[hH]3") then url=WebSearch.attr(attrs,"href");break end
                    end
                    local snippet
                    for _,snippetClass in ipairs({"VwiC3b","IsZvec","BNeawe","yXK7lf"}) do
                        local blocks=WebSearch.blocks(block.html,snippetClass,1)
                        if blocks[1] then snippet=blocks[1].html;break end
                    end
                    if snippet then add(title,snippet,url,snippet) end
                end
            end
            if #results>0 then break end
        end
    end
    return results
end
-- 질의에서 답을 구분할 때 방해가 되는 접속어·부사·안내 문구.
WebSearch.genericWords={}
for word in ("우선 먼저 일단 다음 마지막 현재 이제 이후 이전 그러므로 따라서 그리고 하지만 그러나 또한 또는 혹은 다만 보통 일반적으로 실제 실제로 대부분 일부 모두 반드시 직접 간단히 자세히 참고 참고로 안내 설명 방법 절차 신청 신고 발급 조회 확인 대상 관할 담당 경우 내용 사항 정보 서비스 이용 관련 필요 가능 여부 주소 주민 지역 기관 정부 행정기관 준비물 방문 접수 선택 여러가지 있는 없는 이러한 그러한 같은 다양한 많은 좋은 됩니다 있습니다 가능합니다 바랍니다 중요 주의 무료 유료 여기 저기 이것 그것 아니요 모름"):gmatch("%S+") do
    WebSearch.genericWords[normalized(word)]=true
end
function WebSearch.entityIndex()
    if WebSearch.entitiesRevision==revision then return WebSearch.entities end
    local entities,seen={},{}
    local function add(label)
        local norm=normalized(label)
        local len=charCount(label)
        if seen[norm] or len<2 or len>24 or norm=="" or WebSearch.genericWords[norm] then return end
        if label:find("[,;:/=]") or label:match("^[+-]?%d") then return end
        local words=0;for _ in label:gmatch("%S+") do words=words+1 end
        if words>4 then return end
        seen[norm]=true
        table.insert(entities,{label=label,norm=norm})
    end
    for _,answer in pairs(quizDB) do add(answer) end
    -- 같은 개념의 검색 표기들을 한 후보로 모음. DB 항목 수에는 포함하지 않음.
    for _,alias in ipairs({"주민센터","동주민센터","행정복지센터","동행정복지센터","동사무소","구세주상","구세주 그리스도상","구원자 그리스도상","그리스도 구세주상","Christ the Redeemer","Cristo Redentor","예수상"}) do add(alias) end
    table.sort(entities,function(a,b)
        if #a.norm==#b.norm then return a.norm<b.norm end
        return #a.norm>#b.norm
    end)
    WebSearch.entities,WebSearch.entitiesRevision=entities,revision
    return entities
end
function WebSearch.official(host)
    return host=="gov.kr" or host:sub(-7)==".gov.kr" or host:sub(-6)==".go.kr" or host:sub(-4)==".gov"
end
function WebSearch.queries(question)
    local natural=cleanText(question):gsub("[!?]","")
    for _,ending in ipairs({"무엇이라고 할까요","무엇이라고 하나요","무엇일까요","무엇인가요","누구일까요","누구인가요","어디일까요","어디인가요","몇 개일까요"}) do
        natural=natural:gsub(ending,"")
    end
    natural=trim(natural)
    local tokens=descriptionTokens(question)
    local remove={};for word in ("무엇 할까요 하나요 일까요 무엇일까 이르 부르 하러 가기 어느 뒤 앞"):gmatch("%S+") do remove[word]=true end
    local useful={}
    for _,token in ipairs(tokens) do
        if not remove[token] and not WebSearch.genericWords[token] and #useful<9 then table.insert(useful,token) end
    end
    local keywords=table.concat(useful," ")
    local out,seen={},{}
    local function add(q)
        q=trim(q)
        if q~="" and not seen[normalized(q)] then seen[normalized(q)]=true;table.insert(out,q) end
    end
    -- 처음부터 '정답'만 덧붙이지 않음: 일반 설명 문서도 찾을 수 있게 함.
    add(natural)
    add(keywords)
    if #out<2 then add(natural.." 이름") end
    return out
end

-- 단어의 일부를 별개 정답으로 세지 않음: '인권이란'에서 나라 '이란' 추출 금지.
function WebSearch.wordByte(byte)
    return byte and ((byte>=48 and byte<=57) or (byte>=65 and byte<=90) or (byte>=97 and byte<=122) or byte>=128)
end
function WebSearch.mention(text,label)
    text=WebSearch.plain(text):lower()
    label=WebSearch.plain(label):lower()
    for _,mark in ipairs({"‘","’","“","”","「","」","『","』","（","）","·","–","—"," "}) do text=text:gsub(mark," ") end
    local pattern=label:gsub("(%p)","%%%1"):gsub("%s+","%%s*")
    if pattern=="" then return false end
    local start=1
    while true do
        local s,e=text:find(pattern,start)
        if not s then return false end
        if not WebSearch.wordByte(text:byte(s-1)) then
            local tail=text:sub(e+1)
            if not WebSearch.wordByte(text:byte(e+1)) then return true,s,e,tail end
            for _,ending in ipairs({"이라는","이란","이라고","라고","입니다","이다","이며","이고"}) do
                if tail:sub(1,#ending)==ending then return true,s,e,tail end
            end
            for _,particle in ipairs({"에서는","에게는","으로는","에서","에게","으로","에는","은","는","을","를","이","가","와","과","도","의","에","로","란"}) do
                if tail:sub(1,#particle)==particle and not WebSearch.wordByte(tail:byte(#particle+1)) then return true,s,e,tail end
            end
        end
        start=e+1
    end
end
function WebSearch.questionKind(question)
    local q=normalized(question):gsub("누구나",""):gsub("몇몇","일부")
    for _,term in ipairs({"몇","얼마","개수","연도","년도","온도의값","제곱값","확률의값"}) do if q:find(term,1,true) then return "number" end end
    if q:find("언제",1,true) or q:find("어느시대",1,true) or q:find("어느시기",1,true) then return "date" end
    for _,term in ipairs({"어느나라","어떤나라","무슨나라","나라이름","나라의이름","국가의이름","나라는","나라를","국가는","국가를"}) do if q:find(term,1,true) then return "country" end end
    for _,term in ipairs({"누구","어떤인물","어느인물","인물은","사람은","작가는","작곡가는","가수는","저자는"}) do if q:find(term,1,true) then return "person" end end
    for _,term in ipairs({"사이트","홈페이지","웹서비스"}) do if q:find(term,1,true) then return "website" end end
    for _,term in ipairs({"어디","어느도시","어떤도시","장소","지명","동네행정기관","어느기관","어떤기관","기관의이름","어떤시설","어느학교","교육기관","교육시설","배우는곳"}) do if q:find(term,1,true) then return "place" end end
    for _,term in ipairs({"권리","권한","개념","용어","이론","현상","성질","원리","무엇이라고","무엇이라","무슨말"}) do if q:find(term,1,true) then return "concept" end end
    return "open"
end
function WebSearch.countrySet()
    if WebSearch.countryRevision==revision then return WebSearch.countries end
    local countries={}
    for key in pairs(quizDB) do
        local country=key:match("^(.-)의 수도$")
        if country then countries[normalized(country)]=true end
    end
    for _,name in ipairs({"한국","대한민국","북한","이란","미국","영국","중국","일본","러시아"}) do countries[normalized(name)]=true end
    WebSearch.countries,WebSearch.countryRevision=countries,revision
    return countries
end
function WebSearch.typeFits(question,answer)
    local kind=WebSearch.questionKind(question)
    local a=normalized(answer)
    local numeric=answer:match("^%s*[+-]?%d")~=nil
    if numeric and kind~="number" and kind~="date" then return false end
    if WebSearch.countrySet()[a] and kind~="country" and kind~="open" then return false end
    if kind=="concept" and (a=="학교" or a=="국민" or a=="주민" or a=="사람" or a=="인간" or a=="대한민국") then return false end
    if kind=="number" and not answer:find("%d") then
        local words={}
        -- 숫자 대신 한글로 표현된 짧은 정수도 허용.
        for word in ("영 공 하나 둘 셋 넷 다섯 여섯 일곱 여덟 아홉 열 백 천 만 일 이 삼 사 오 육 칠 팔 구 십"):gmatch("%S+") do words[word]=true end
        if not words[a] then return false end
    end
    return true
end
function WebSearch.titleName(title)
    title=title:gsub("이란%-","이란 - ")
    local name=title:match("^(.-)%s+%-%s+") or title:match("^(.-)%s+|%s+") or title:match("^(.-)%s+–%s+") or title:match("^(.-)%s+—%s+") or title
    name=trim(name:gsub("[%?!]+$",""))
    for _,ending in ipairs({"이란 무엇인가","이란 무엇인가요","이란","의 의미","의 뜻","의 개념","의 정의","란"}) do
        if name:sub(-#ending)==ending then
            local root=trim(name:sub(1,#name-#ending))
            if charCount(root)>=2 then return root end
        end
    end
    return name
end
-- 직업·역할 이름 자체를 사람의 고유 이름으로 집계하지 않음.
WebSearch.roleNouns={}
for role in ("사람 인물 선수 축구선수 공격수 수비수 골키퍼 미드필더 감독 작가 저자 시인 화가 조각가 작곡가 음악가 가수 배우 학자 과학자 수학자 물리학자 철학자 사상가 대통령 황제 왕 정치가 독립운동가 장군 군인 경찰관 소방관 농부 어부 목수 건축가 프로그래머 교사 학생 의사 간호사 약사 조종사 선장 기자 통역사 번역가 사서"):gmatch("%S+") do WebSearch.roleNouns[normalized(role)]=true end
-- 인물 질문에는 인명 사전 또는 인물 역할의 근거가 있어야 함.
function WebSearch.peopleIndex()
    if WebSearch.peopleRevision==revision then return WebSearch.people end
    local people={}
    local function add(name)
        if type(name)~="string" or charCount(name)<2 or charCount(name)>24 or name:match("^[+-]?%d") then return end
        if name:find("[,;:/=]") or WebSearch.genericWords[normalized(name)] or WebSearch.roleNouns[normalized(name)] or WebSearch.countrySet()[normalized(name)] then return end
        people[normalized(name)]=name
    end
    for key,answer in pairs(quizDB) do
        local k=normalized(key)
        local identified=false
        for _,marker in ipairs({"의작가","의저자","작곡한사람","그린사람","부른가수","부른그룹","을쓴사람","를쓴사람","쓴시인","만든작가","설계한건축가","발견한과학자"}) do
            if k:find(marker,1,true) then identified=true;break end
        end
        for _,ending in ipairs({"인물","인물은","사람","학자","철학자","사상가","작곡가","화가","조각가","시인","작가","가수","독립운동가","장군","대통령","황제","선수","왕"}) do
            if k:sub(-#ending)==ending then identified=true;break end
        end
        if identified then add(answer) end
    end
    -- 종목을 답으로 가진 역방향 항목만 있던 선수들도 인명으로 구분.
    for _,name in ipairs({"음바페","킬리안 음바페","Kylian Mbappe","Kylian Mbappé","Mbappe","Mbappé","메시","리오넬 메시","Lionel Messi","손흥민","박지성","황희찬","김민재","이강인","황인범","조규성","안정환","차범근","차두리","이천수","이동국","이영표","홍명보","거스 히딩크","호날두","크리스티아누 호날두","네이마르","펠레","디에고 마라도나","마라도나","지네딘 지단","제프 허스트","해리 케인","앙투안 그리에즈만","카림 벤제마","올리비에 지루","우스만 뎀벨레","비니시우스 주니오르","엘링 홀란","로베르트 레반도프스키","마이클 조던","코비 브라이언트","르브론 제임스","스테픈 커리","김연아","김연경","박세리","박태환","우사인 볼트","마이클 펠프스","로저 페더러","라파엘 나달","노바크 조코비치","세리나 윌리엄스","타이거 우즈","베이브 루스","오타니 쇼헤이","류현진","박찬호","이승엽"}) do add(name) end
    WebSearch.people,WebSearch.peopleRevision=people,revision
    return people
end
function WebSearch.personRole(record,label)
    local text=normalized(WebSearch.plain(record.title.." "..record.snippet))
    local a=normalized(label)
    for _,role in ipairs({"선수","공격수","수비수","골키퍼","미드필더","축구선수","작가","작곡가","화가","시인","가수","배우","감독","학자","수학자","물리학자","철학자","정치가","대통령","황제","독립운동가","장군"}) do
        if text:find(a..role,1,true) or text:find(role..a,1,true) or text:find(role.."인"..a,1,true) or text:find(role.."는"..a,1,true) or text:find(role.."은"..a,1,true) then return true end
    end
    return false
end
function WebSearch.hatTrickQuestion(question)
    local q=normalized(question)
    if q:find("감독은",1,true) or q:find("감독의이름",1,true) or q:find("골키퍼는",1,true) or q:find("주심은",1,true) then return false end
    return q:find("세골",1,true) or q:find("3골",1,true) or q:find("해트트릭",1,true)
end
function WebSearch.goalLinked(record,label)
    local text=normalized(WebSearch.plain(record.snippet))
    local people=WebSearch.peopleIndex()
    local wanted=normalized(preferredGameAnswer("",label))
    local mentioned={}
    for norm,name in pairs(people) do
        if text:find(norm,1,true) and WebSearch.mention(record.snippet,name) then
            local canonical=normalized(preferredGameAnswer("",name))
            local start=1
            while true do
                local s,e=text:find(norm,start,true)
                if not s then break end
                table.insert(mentioned,{start=s,finish=e,person=canonical})
                start=e+1
            end
        end
    end
    local linked=false
    for _,goal in ipairs({"세골","3골","해트트릭"}) do
        local start=1
        while true do
            local gs,ge=text:find(goal,start,true)
            if not gs then break end
            local nearest,minimum,ambiguous=nil,math.huge,false
            for _,person in ipairs(mentioned) do
                local distance=math.max(0,gs-person.finish,person.start-ge)
                if distance<minimum then nearest,minimum,ambiguous=person.person,distance,false
                elseif distance==minimum and person.person~=nearest then ambiguous=true end
            end
            if nearest==wanted and minimum<=85 and not ambiguous then linked=true end
            start=ge+1
        end
    end
    return linked
end
function WebSearch.personFits(question,record,label)
    if WebSearch.questionKind(question)~="person" then return true end
    if WebSearch.roleNouns[normalized(label)] then return false end
    if not WebSearch.peopleIndex()[normalized(label)] and not WebSearch.personRole(record,label) then return false end
    if WebSearch.hatTrickQuestion(question) and not WebSearch.goalLinked(record,label) then return false end
    return true
end

function WebSearch.supports(question,record,label,kind,ratio)
    local present,s,e=WebSearch.mention(record.title.." "..record.snippet,label)
    if not present then return false end
    if WebSearch.questionKind(question)=="person" then
        if not WebSearch.personFits(question,record,label) then return false end
        if WebSearch.hatTrickQuestion(question) then return ratio>=0.25 and WebSearch.goalLinked(record,label) end
    end
    if kind=="explicit" then return ratio>=0.3 end
    if kind=="definition" then return ratio>=0.35 end
    if kind=="title" then
        return normalized(WebSearch.titleName(record.title))==normalized(label) and ratio>=0.3
    end
    local snippet=WebSearch.plain(record.snippet)
    local found,_,finish,after=WebSearch.mention(snippet,label)
    if found then
        local tail=trim(after or "")
        for _,ending in ipairs({"이란","란","이라는","이라고","라고","입니다","이다"}) do
            if tail:sub(1,#ending)==ending and ratio>=0.35 then return true end
        end
    end
    -- 장소 질문의 목적어 표현은 정의 문장 없이도 사용되므로 별도로 검사.
    if WebSearch.questionKind(question)=="place" and ratio>=0.4 then return true end
    return false
end

function WebSearch.candidate(text,question)
    text=WebSearch.plain(text):gsub("：",":")
    text=trim(text:gsub("^[%s:\"'(%[]+",""):gsub("[%s:\"')%]%.!%?]+$",""))
    for _,quote in ipairs({"‘","’","“","”","「","」","『","』"}) do text=text:gsub(quote,"") end
    text=trim(text)
    for _,ending in ipairs({"입니다","이다","라고 합니다","라고 한다","이라고 합니다","이라고 한다"}) do
        if text:sub(-#ending)==ending then text=trim(text:sub(1,#text-#ending));break end
    end
    if text=="" or charCount(text)>24 or text:find("[<>{}%[%]`\\;/=]") or text:find("https?://") then return nil end
    local words=0;for _ in text:gmatch("%S+") do words=words+1 end
    if words>5 then return nil end
    for _,intro in ipairs({"우선 ","먼저 ","일단 ","보통 ","일반적으로 "}) do
        if text:sub(1,#intro)==intro then text=trim(text:sub(#intro+1)) end
    end
    local norm=normalized(text)
    if norm=="" or WebSearch.genericWords[norm] or WebSearch.mention(question,text) then return nil end
    for _,particle in ipairs({"은","는","이","가","을","를","도","의"}) do
        if norm:sub(-#particle)==particle and WebSearch.genericWords[norm:sub(1,#norm-#particle)] then return nil end
    end
    for _,phrase in ipairs({"찾는법","하는법","하는방법","총정리","완벽정리","신청방법","신고방법","발급방법","확인방법","바로가기","가이드","절차안내"}) do
        if norm:find(phrase,1,true) then return nil end
    end
    for _,ending in ipairs({"습니다","됩니다","합니다","하세요","있다","된다","한다","하는","되는","하고","으로","에서","에게","에는"}) do
        if norm:sub(-#ending)==ending then return nil end
    end
    if norm:match("^%d+년$") then
        local q=normalized(question)
        if not (q:find("언제",1,true) or q:find("몇년",1,true) or q:find("연도",1,true) or q:find("년도",1,true) or q:find("시기",1,true) or q:find("일어난해",1,true) or q:find("시작된해",1,true) or q:find("태어난해",1,true)) then return nil end
    end
    local forbidden={"정답","질문","검색","블로그","티스토리","네이버","google","duckduckgo","더보기","출처","관련문서","누구","무엇","무슨","어디","아닙니다","모릅니다"}
    for _,token in ipairs(forbidden) do if norm:find(token,1,true) then return nil end end
    if not WebSearch.typeFits(question,text) then return nil end
    return text
end
function WebSearch.choose(question,records)
    local queryTokens=descriptionTokens(question)
    local pool={}
    local function relevance(record)
        local hay=normalized(record.title.." "..record.snippet)
        local matches=0
        for _,token in ipairs(queryTokens) do if hay:find(token,1,true) then matches=matches+1 end end
        if #queryTokens==0 then return 0,0 end
        return matches/#queryTokens,matches
    end
    for _,record in ipairs(records) do
        local ratio,matches=relevance(record)
        if matches>=2 or (#queryTokens<=2 and matches>=1) then
            local function add(text,kind)
                local answer=WebSearch.candidate(text,question)
                if not answer then return end
                if not WebSearch.personFits(question,record,answer) then return end
                if not WebSearch.mention(record.title.." "..record.snippet,answer) then return end
                local supported=WebSearch.supports(question,record,answer,kind,ratio)
                answer=preferredGameAnswer(question,answer)
                local norm=normalized(answer)
                local candidate=pool[norm]
                if not candidate then
                    candidate={answer=answer,domains={},evidence={},explicitDomains={},entityDomains={},officialDomains={},supportedDomains={},evidenceHosts={},strength={},maxRelevance=0}
                    pool[norm]=candidate
                end
                candidate.domains[record.host]=true
                if supported then candidate.supportedDomains[record.host]=true end
                if kind=="explicit" then candidate.explicitDomains[record.host]=true end
                if kind=="entity" then candidate.entityDomains[record.host]=true end
                if WebSearch.official(record.host) then candidate.officialDomains[record.host]=true end
                local strength=({explicit=5,definition=3,title=2,highlight=1,entity=2})[kind] or 0
                candidate.strength[record.host]=math.max(candidate.strength[record.host] or 0,strength)
                candidate.maxRelevance=math.max(candidate.maxRelevance,ratio)
                if #candidate.evidence<4 and not candidate.evidenceHosts[record.host] then
                    candidate.evidenceHosts[record.host]=true
                    table.insert(candidate.evidence,{title=record.title,url=record.url,snippet=record.snippet})
                end
            end
            local text=record.snippet:gsub("：",":")
            for _,prefix in ipairs({"정답은","정답:","답은","답:","수도는","작곡가는","작가는","저자는","이름은","명칭은","선수는","감독은","공격수는","시인은","수학자는","화가는","철학자는"}) do
                local pos=1
                while true do
                    local _,e=text:find(prefix,pos,true)
                    if not e then break end
                    local tail=trim(text:sub(e+1)):gsub("^:%s*","")
                    local cutoff
                    for _,ending in ipairs({"입니다","이다","라고","이라","이며","이고","였다","이었다","였으며","였다"}) do
                        local at=tail:find(ending,1,true)
                        if at and (not cutoff or at<cutoff) then cutoff=at end
                    end
                    local phrase=cutoff and tail:sub(1,cutoff-1) or tail:match("^([^%.!%?]+)")
                    if phrase then add(phrase,prefix:find("답",1,true) and "explicit" or "definition") end
                    pos=e+1
                end
            end
            for word in text:gmatch("(%S+)입니다") do add(word,"definition") end
            for word in text:gmatch("(%S+)이다") do add(word,"definition") end
            for inside in record.raw:gmatch("<[bB][^>]*>(.-)</[bB]>") do add(inside,"highlight") end
            for inside in record.raw:gmatch("<[sS][tT][rR][oO][nN][gG][^>]*>(.-)</[sS][tT][rR][oO][nN][gG]>") do add(inside,"highlight") end
            -- 문서가 '정답은'이라고 쓰지 않아도 본문에 등장한 사전의 명사·이름을 찾음.
            local evidenceText=record.title.." "..record.snippet
            local evidenceNorm=normalized(evidenceText)
            local longerMatches={}
            local used=0
            for _,entity in ipairs(WebSearch.entityIndex()) do
                if evidenceNorm:find(entity.norm,1,true) and WebSearch.mention(evidenceText,entity.label) then
                    local inside=false
                    for _,longer in ipairs(longerMatches) do
                        if longer:find(entity.norm,1,true) then inside=true;break end
                    end
                    if not inside then
                        add(entity.label,"entity")
                        table.insert(longerMatches,entity.norm)
                        used=used+1
                        if used>=10 then break end
                    end
                end
            end
            local title=WebSearch.titleName(record.title)
            add(title,"title")
        end
    end
    local ranked={}
    for _,candidate in pairs(pool) do
        local votes,explicit,entityVotes,official,strength,supported=0,0,0,0,0,0
        for _ in pairs(candidate.domains) do votes=votes+1 end
        for _ in pairs(candidate.explicitDomains) do explicit=explicit+1 end
        for _ in pairs(candidate.entityDomains) do entityVotes=entityVotes+1 end
        for _ in pairs(candidate.officialDomains) do official=official+1 end
        for _,value in pairs(candidate.strength) do strength=strength+value end
        for _ in pairs(candidate.supportedDomains) do supported=supported+1 end
        candidate.sources,candidate.explicit,candidate.official,candidate.supportedSources=votes,explicit,official,supported
        candidate.score=supported*15+votes*2+explicit*3+entityVotes+strength+candidate.maxRelevance
        table.insert(ranked,candidate)
    end
    table.sort(ranked,function(a,b)
        if a.score==b.score then return a.answer<b.answer end
        return a.score>b.score
    end)
    local top=ranked[1]
    if not top then return {answer=nil,reason="검색 결과에서 짧은 정답 후보를 추리지 못했습니다.",records=records} end
    local runner=ranked[2]
    local uncontested=not runner or top.score-runner.score>=3
    top.agreement=top.supportedSources>=2 and uncontested
    top.explicitOnly=top.supportedSources>=1 and ((top.explicit>=1 and top.maxRelevance>=0.75) or (top.official>=1 and top.maxRelevance>=0.5)) and uncontested
    top.alternatives={}
    for i=2,math.min(4,#ranked) do
        if ranked[i].supportedSources>=1 then table.insert(top.alternatives,{answer=ranked[i].answer,sources=ranked[i].sources}) end
    end
    top.reason=top.agreement and "서로 다른 도메인의 답 설명 문맥이 일치했습니다." or "언급 수와 별개로 답을 설명하는 문맥이 부족하거나 후보가 충돌합니다."
    top.records=records
    return top
end
function WebSearch.search(question,googleFirst,keepGoing)
    local plans={}
    local queries=WebSearch.queries(question)
    if googleFirst then table.insert(plans,{engine="Google",query=queries[1]}) end
    for i=1,math.min(2,#queries) do table.insert(plans,{engine="DuckDuckGo",query=queries[i]}) end
    local failures,allRecords,bestCandidate={},{},nil
    local start=os.clock()
    local attempts=0
    for _,plan in ipairs(plans) do
        if keepGoing and not keepGoing() then return {cancelled=true} end
        if os.clock()-start>12 then break end
        attempts=attempts+1
        local engine=plan.engine
        local query=WebSearch.urlEncode(plan.query)
        local url=engine=="Google" and ("https://www.google.com/search?hl=ko&gbv=1&num=10&q="..query)
            or ("https://html.duckduckgo.com/html/?kl=kr-kr&q="..query)
        local html,err,blocked=WebSearch.fetch(url)
        if html then
            local records=WebSearch.records(html,engine)
            if #records>0 then
                for _,record in ipairs(records) do table.insert(allRecords,record) end
                local result=WebSearch.choose(question,allRecords)
                result.engine=googleFirst and engine=="DuckDuckGo" and "Google + DuckDuckGo" or engine
                result.queryUrl,result.attempts=url,attempts
                if result.agreement then return result end
                if result.answer then bestCandidate=result end
                table.insert(failures,engine..": "..result.reason)
            else
                table.insert(failures,engine..": 검색 결과 HTML을 해석하지 못했습니다.")
            end
        else
            table.insert(failures,engine..": "..tostring(err))
            if blocked and engine=="DuckDuckGo" then
                if bestCandidate then bestCandidate.blocked=true;bestCandidate.reason=bestCandidate.reason.."\n추가 검색이 차단되었습니다.";return bestCandidate end
                return {blocked=true,attempts=attempts,reason=table.concat(failures,"\n")}
            end
        end
    end
    if bestCandidate then bestCandidate.attempts=attempts;return bestCandidate end
    return {answer=nil,attempts=attempts,reason=table.concat(failures,"\n")}
end

-- 4. WindUI. 실패 시 로드 잠금을 풀어 다시 실행할 수 있게 함.
local beforeRoots={}
for _,child in ipairs(PG:GetChildren()) do beforeRoots[child]=true end
local okCore, CoreGui=pcall(function() return game:GetService("CoreGui") end)
if okCore then pcall(function() for _,c in ipairs(CoreGui:GetChildren()) do beforeRoots[c]=true end end) end
local Wind
local windOK, windError=pcall(function()
    Wind=loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/WindUI/main/dist/main.lua"))()
end)
