-- 소유 UI 루트를 제외해 스크립트가 자신의 '인식된 질문'을 다시 읽지 않게 함.
local ownedRoots={}
local function markNewRoots(parent)
    for _,child in ipairs(parent:GetChildren()) do
        if not beforeRoots[child] then ownedRoots[child]=true end
    end
end
markNewRoots(PG)
if okCore then pcall(function() markNewRoots(CoreGui) end) end
local function isOwnUI(object)
    local cur=object
    while cur do
        if ownedRoots[cur] then return true end
        local name=cur.Name:lower()
        if name:find("windui",1,true) then return true end
        cur=cur.Parent
    end
    return false
end
local function effectivelyVisible(object)
    if not object.Parent or not object:IsDescendantOf(PG) or isOwnUI(object) then return false end
    if object.AbsoluteSize.X<=0 or object.AbsoluteSize.Y<=0 then return false end
    local cur=object
    while cur and cur~=PG do
        if cur:IsA("GuiObject") and not cur.Visible then return false end
        if cur:IsA("ScreenGui") and not cur.Enabled then return false end
        local name=cur.Name:lower()
        if name=="chat" or name:find("textchat",1,true) or name:find("bubblechat",1,true) then return false end
        cur=cur.Parent
    end
    return true
end
local labels,boxes={},{}
local function register(object)
    if object:IsA("TextLabel") or object:IsA("TextButton") then labels[object]=true end
    if object:IsA("TextBox") then boxes[object]=true end
end
for _,object in ipairs(PG:GetDescendants()) do register(object) end
local addedConnection=PG.DescendantAdded:Connect(register)
local removingConnection=PG.DescendantRemoving:Connect(function(object)
    labels[object],boxes[object]=nil,nil
end)

local questionObject=nil
local questionHints={"까요","무엇","보세요","어디","누구","몇","어느","인가","입니까","뜻","이름","정답","?"}
local function getQuestionText()
    local bestText,bestObject,bestScore="",nil,-math.huge
    for object in pairs(labels) do
        if effectivelyVisible(object) then
            local t=cleanText(object.Text)
            local length=charCount(t)
            local hint=false
            for _,token in ipairs(questionHints) do
                if has(t,token) then hint=true;break end
            end
            if length>=6 and length<=800 and hint and not has(t,"관전 연습")
                and not has(t,"다시 듣기") and not has(t,"여기에 정답")
                and not has(t,"여기를 누르면") and not has(t,"정답을 쓰세요!")
                and not has(t,"풀이 중엔 채팅") and not has(t,"모두 제출했어요")
                and not has(t,"다음 라운드") and not has(t,"정답 첫 자음") then
                local score=math.min(length,250)
                if has(t,"?") then score=score+80 end
                local name=object.Name:lower()
                if name:find("question",1,true) or name:find("quiz",1,true) then score=score+100 end
                if has(t,"코인") or has(t,"로벅스") or has(t,"구매") then score=score-180 end
                if score>bestScore then bestText,bestObject,bestScore=t,object,score end
            end
        end
    end
    questionObject=bestObject
    return bestText
end
local function commonAncestorDepth(a,b)
    if not a or not b then return 0 end
    local ancestors={}
    local current=a
    while current and current~=PG do ancestors[current]=true;current=current.Parent end
    current=b
    while current and current~=PG do
        if ancestors[current] then
            local depth=0
            while current and current~=PG do depth=depth+1;current=current.Parent end
            return depth
        end
        current=current.Parent
    end
    return 0
end
local function getAnswerBox()
    local best,bestScore=nil,-math.huge
    for box in pairs(boxes) do
        if effectivelyVisible(box) and box.AbsoluteSize.X>100 and box.TextEditable then
            local placeholder=cleanText(box.PlaceholderText)
            local name=box.Name:lower()
            local score=commonAncestorDepth(questionObject,box)*30
            if has(placeholder,"정답") then score=score+160 end
            if has(placeholder,"입력") or has(placeholder,"쓰세요") then score=score+50 end
            if name:find("answer",1,true) then score=score+100 end
            if has(placeholder,"검색") or name:find("search",1,true) then score=score-250 end
            if score>bestScore then best,bestScore=box,score end
        end
    end
    return best
end
local function humanType(text,box)
    if typingBusy or not box then return end
    cancelTyping()
    local generation=typingGeneration
    typingBusy=true
    local expectedQuestion=lastQuestionText
    local boundaries={}
    for byteIndex in utf8.codes(text) do table.insert(boundaries,byteIndex) end
    table.insert(boundaries,#text+1)
    local ok=pcall(function() box.Text="" end)
    if not ok then typingBusy=false;return end
    task.spawn(function()
        for i=1,#boundaries-1 do
            if generation~=typingGeneration or not autoFill or expectedQuestion~=lastQuestionText then break end
            if not box.Parent or not effectivelyVisible(box) then
                if generation==typingGeneration then lastTypedQuestion="" end
                break
            end
            local wrote=pcall(function() box.Text=text:sub(1,boundaries[i+1]-1) end)
            if not wrote then
                if generation==typingGeneration then lastTypedQuestion="" end
                break
            end
            task.wait(math.random(40,90)/1000)
        end
        if generation==typingGeneration then typingBusy=false end
    end)
end


-- 검색은 별도 작업에서 수행. 렌더링/질문 감지/내장 검색을 HTTP 응답으로 막지 않음.
local function currentWebQuestion(q,generation)
    return running and webGeneration==generation and lastQuestionText==q and getQuestionText()==q
end
local function webDetails(result)
    local lines={result.engine or "웹 검색"}
    if result.answer then
        table.insert(lines,"후보: "..result.answer.." · 도메인 "..tostring(result.sources or 0).."개 / 답 근거 "..tostring(result.supportedSources or 0).."개")
    end
    table.insert(lines,result.reason or "정답 후보 없음")
    if result.attempts then table.insert(lines,"검색어 조합 "..result.attempts.."회 확인") end
    for _,alternative in ipairs(result.alternatives or {}) do
        table.insert(lines,"다른 후보: "..alternative.answer.." ("..alternative.sources.."개 도메인)")
    end
    local seen={}
    for _,record in ipairs(result.evidence or {}) do
        local host=WebSearch.host(record.url)
        if host and not seen[host] then
            seen[host]=true
            table.insert(lines,host.." · "..record.title)
        end
    end
    return table.concat(lines,"\n")
end
local function applyWebResult(q,result)
    result.question=q
    lastWebResult=result
    -- 검색 도중 사용자가 등록한 사전 항목이 있으면 그 답이 우선.
    local localAnswer=lookup(q)
    if localAnswer then return end
    local accepted=result.answer and (result.agreement or (not strictWeb and result.explicitOnly))
    setDesc(webStatus,webDetails(result))
    if accepted then
        currentFoundAnswer=result.answer
        currentIsWeb=true
        lastTypedQuestion=""
        setDesc(answerStatus,"웹 후보: "..result.answer.."\n"..tostring(result.engine).." · 답 근거 "..tostring(result.supportedSources or 0).."개")
    elseif result.answer then
        currentFoundAnswer=""
        currentIsWeb=false
        setDesc(answerStatus,"웹 후보: "..result.answer.."\n출처 확인이 부족하여 자동 입력 보류. 웹 검색 탭에서 확인하세요.")
    else
        currentFoundAnswer=""
        currentIsWeb=false
        setDesc(answerStatus,"내장 답 없음 · 웹 정답 후보도 찾지 못했습니다.\n웹 검색 탭에서 오류/차단 상태를 확인하세요.")
    end
end
local function rememberWeb(q,result)
    if not webCache[q] then table.insert(webCacheOrder,q) end
    webCache[q]={at=os.clock(),result=result}
    while #webCacheOrder>80 do webCache[table.remove(webCacheOrder,1)]=nil end
end
startWebSearch=function(q,force)
    if not running or (not onlineEnabled and not force) or q=="" then return false end
    if charCount(q)>600 then setDesc(webStatus,"질문이 너무 길어 검색하지 않았습니다.");lastWebQuestion=q;return false end
    local now=os.clock()
    if now<webBlockedUntil then
        setDesc(webStatus,"검색 제공자가 요청을 차단했습니다. 재요청 대기 "..math.ceil(webBlockedUntil-now).."초")
        return false
    end
    if webWorkers>=2 then
        setDesc(webStatus,"이전 HTTP 요청이 아직 끝나지 않았습니다. 응답을 기다리는 중입니다.")
        return false
    end
    if webBusy or now-webLastStarted<2 then return false end
    local generation=webGeneration
    if not force then
        local cached=webCache[q]
        local ttl=cached and cached.result.answer and 300 or 25
        if cached and now-cached.at<ttl then
            lastWebQuestion=q
            if currentWebQuestion(q,generation) then applyWebResult(q,cached.result) end
            return true
        end
    end
    webBusy=true
    webWorkers=webWorkers+1
    webLastStarted=now
    webRequestSequence=webRequestSequence+1
    local requestId=webRequestSequence
    webActiveRequest=requestId
    lastWebQuestion=q
    lastWebResult=nil
    setDesc(webStatus,(preferGoogle and "Google → DuckDuckGo HTML" or "DuckDuckGo HTML").." 검색 중...\n"..q)
    setDesc(answerStatus,"사전 답 없음 · 웹 검색 중...")
    local finished=false
    local function finish(result)
        if finished then return end
        finished=true
        if webActiveRequest==requestId then webBusy=false end
        if result.blocked then webBlockedUntil=os.clock()+60 end
        if currentWebQuestion(q,generation) then
            if not result.cancelled then
                rememberWeb(q,result)
                applyWebResult(q,result)
            end
        end
    end
    task.delay(preferGoogle and 17 or 14,function()
        finish({reason="웹 검색 제한 시간 초과. 검색 제공자나 HTTP 경로의 응답이 지연되고 있습니다."})
    end)
    task.spawn(function()
        local ok,result=pcall(WebSearch.search,q,preferGoogle,function() return currentWebQuestion(q,generation) and not finished end)
        webWorkers=math.max(0,webWorkers-1)
        if not ok then result={reason="검색 처리 오류: "..tostring(result)} end
        finish(result)
    end)
    return true
end

-- 5. 감지 루프. 자동 제출은 기존 코드와 같이 하지 않음.
ENV.GoldenBell_Stop=function()
    running=false
    webGeneration=webGeneration+1
    cancelTyping()
    addedConnection:Disconnect()
    removingConnection:Disconnect()
    ENV.GoldenBell_QAloaded=nil
end
if loadWarning then setDesc(answerStatus,"기존 사전 읽기 실패. 내장 사전으로 실행합니다.\n"..loadWarning) end
local lastError=""
task.spawn(function()
    while running and task.wait(0.5) do
        local ok,err=pcall(function()
            local q=getQuestionText()
            if q=="" then
                if lastQuestionText~="" then
                    cancelTyping()
                    lastQuestionText,currentFoundAnswer,lastTypedQuestion="","",""
                    webGeneration=webGeneration+1
                    lastWebQuestion,lastWebResult,currentIsWeb="",nil,false
                    setDesc(questionStatus,"질문을 기다리는 중...")
                    setDesc(answerStatus,"-")
                end
                return
            end
            if q~=lastQuestionText or revision~=lastRevision then
                cancelTyping()
                lastQuestionText,lastRevision,lastTypedQuestion=q,revision,""
                webGeneration=webGeneration+1
                lastWebQuestion,lastWebResult,currentIsWeb="",nil,false
                setDesc(questionStatus,q)
                local answer,key,cat=lookup(q)
                currentFoundAnswer=answer or ""
                if answer then
                    setDesc(answerStatus,"정답: "..answer.."\n분류: "..cat.." · 키: "..key)
                else
                    setDesc(answerStatus,"등록된 답을 찾지 못했습니다. 추가/삭제 탭에서 등록하세요.")
                end
            end
            if onlineEnabled and currentFoundAnswer=="" and lastWebQuestion~=q then
                startWebSearch(q,false)
            end
            if autoFill and currentFoundAnswer~="" and not typingBusy and lastTypedQuestion~=q then
                local box=getAnswerBox()
                if box then
                    lastTypedQuestion=q
                    humanType(currentFoundAnswer,box)
                end
            end
        end)
        if not ok and tostring(err)~=lastError then
            lastError=tostring(err)
            warn("[GoldenBell] 감지 오류: "..lastError)
        end
    end
end)
print("[GoldenBell] v14 Ready — 내장 "..baseCount.."개 / 현재 "..dbCount.."개")
